data_hex = ""  # your big hex string
data = bytes.fromhex(data_hex)
import itertools, string

alphabet = string.ascii_letters  # or ascii_letters + digits
max_len = 4  # or 5 if you feel brave


def xor_with_key(data, key):
    key = key.encode()
    klen = len(key)
    return bytes(b ^ key[i % klen] for i, b in enumerate(data))


for L in range(1, max_len + 1):
    for key in itertools.product(alphabet, repeat=L):
        key_str = "".join(key)
        out = xor_with_key(data, key_str)
        if b"actf{" in out or b"amateurs" in out or b"flag{" in out:
            print("FOUND KEY:", key_str)
            print(out[:200])
            raise SystemExit
